SELECT nextval('TRIALS.SEQ_PERSONAS_ID'), 0, 'Gilberto', 'Capturista de Atención a Publico', '', '', 1, 'capturistapublico@capturistapublico.dev', '', '', '1992-10-10', EC.PN_ID, '', E.PN_ID, 0, 'a646fa17-9b7d-4cd2-a7e0-316f4a1877f8', 3, 2
